function lowAndHigh(temperatures) {
  let low = temperatures[0]
  let high = temperatures[0]
  for (const t of temperatures) {
    if (t < low) low = t
    if (t > high) high = t
  }
  return [low, high]
}

console.log(lowAndHigh([18, 22, 15, 30, 25])) // [15, 30]
